/**
 * TakaKori service worker.
 *
 * Hand-written rather than generated by a plugin, and the reason is specific
 * rather than ideological.
 *
 * `@serwist/turbopack` builds the worker through a Route Handler that prerenders
 * with the root-layout implicit cache tag — a tag every prerendered route in the
 * app carries. `revalidatePath('/', 'layout')` resolves to exactly that tag, and
 * this app calls it on sign-in and sign-out, the two most frequent authenticated
 * events in its life. The documented, reproduced result is that the prerendered
 * worker is evicted, a build-time-only handler runs at request time, and
 * `/serwist/sw.js` returns `ERR_MODULE_NOT_FOUND` — intermittently at first,
 * then 100% of requests once anyone adds `dynamic = 'force-dynamic'`.
 *
 * (`@serwist/next` avoids that but is webpack-only, and Next 16 builds with
 * Turbopack.)
 *
 * So: no build step, no bundler assumption, nothing to go wrong at deploy time.
 * The cost is that hashed asset names cannot be precached by name — which costs
 * nothing, because `/_next/static/` is content-hashed and therefore safe to
 * cache permanently at runtime.
 *
 * **Scope.** This worker caches the *shell* only: documents and static assets.
 * It deliberately does not touch Supabase API traffic. Caching `*.supabase.co`
 * here would mean a second, invisible copy of a financial ledger with its own
 * invalidation rules — and the ledger already has a cache, `lib/client/cache.ts`,
 * which knows about timestamps and offline. Two caches over the same data is
 * the arrangement that produces a balance nobody can explain.
 */

/** Bumped whenever the caching strategy changes, to retire old caches. */
const VERSION = 'v1'

const SHELL_CACHE = `takakori-shell-${VERSION}`
const ASSET_CACHE = `takakori-assets-${VERSION}`
const KEEP = new Set([SHELL_CACHE, ASSET_CACHE])

/**
 * Precached at install so the app opens with no network at all.
 *
 * `/dashboard` is the manifest's `start_url` and the tab bar's first stop, so it
 * is the one screen that must render from cache. It redirects to `/login` when
 * signed out, which is itself cached, so a signed-out launch lands somewhere
 * real rather than on an error page.
 */
const SHELL_URLS = ['/', '/login', '/offline']

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // `reload` so installing never serves a precache entry from the HTTP cache,
      // which would bake today's build into a worker's first run.
      .then((cache) =>
        Promise.allSettled(
          SHELL_URLS.map((url) => cache.add(new Request(url, { cache: 'reload' }))),
        ),
      )
      .then(() => self.skipWaiting()),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => !KEEP.has(key)).map((key) => caches.delete(key))),
      ),
  )
  // **No `clients.claim()` here, deliberately.**
  //
  // Claiming makes a live session adopt a new worker *immediately* rather than
  // on its next navigation. It was here to avoid an app left open for a week
  // staying on the old shell — which was never the behaviour it actually bought,
  // and it costs something real.
  //
  // `skipWaiting()` in `install` already means the new worker activates at once.
  // `claim()` is a separate second step: it reassigns control of clients that are
  // *mid-request*. If a user submits the sign-in form while that happens, the
  // navigation aborts and the browser shows an error page instead of a session.
  //
  // That is not hypothetical. With the worker enabled, `layout.spec.ts` failed
  // intermittently with `page.goto: net::ERR_ABORTED` — always at a random width,
  // always during the sign-in step, always in a fresh context that had just
  // installed the worker. Blocking the worker in the suite removed every one of
  // them and halved the suite's runtime. Sign-in is the one navigation this app
  // cannot afford to lose, and it is also the one a first-time visitor triggers
  // within seconds of the worker installing.
  //
  // What is given up is negligible: a page already open keeps the shell it
  // loaded, and the next navigation — a tab, a sign-in, a reload — is served by
  // the new worker, which `skipWaiting` has already made warm with its cache
  // populated.
  //
  // If something later genuinely needs same-session takeover, the correct shape
  // is to claim on an explicit user action — the `skip-waiting` message handler
  // below exists for exactly that — not on every activation.
})

self.addEventListener('message', (event) => {
  // Lets the page force an update, which is how a "reload for the new version"
  // affordance can work without waiting for natural navigation.
  if (event.data === 'skip-waiting') self.skipWaiting()
})

/** Content-hashed, so it can be cached forever. */
function isImmutableAsset(url) {
  return url.pathname.startsWith('/_next/static/') || url.pathname.startsWith('/icons/')
}

async function cacheFirst(request) {
  const cached = await caches.match(request)
  if (cached) return cached

  const response = await fetch(request)
  if (response.ok) {
    const cache = await caches.open(ASSET_CACHE)
    cache.put(request, response.clone())
  }
  return response
}

/**
 * Network-first for documents.
 *
 * The app's data is loaded client-side now, so a document is a small shell with
 * the fixtures for the current build in it. Serving a stale document would run
 * old JavaScript against a new API, which fails in ways that are hard to read.
 * Network-first with a cache fallback gives a fresh shell when there is a
 * connection and *something* when there is not.
 */
async function networkFirstDocument(request) {
  try {
    const response = await fetch(request)
    if (response.ok) {
      const cache = await caches.open(SHELL_CACHE)
      cache.put(request, response.clone())
    }
    return response
  } catch {
    const cached = await caches.match(request)
    if (cached) return cached

    const offline = await caches.match('/offline')
    if (offline) return offline

    return new Response(
      '<!doctype html><meta charset="utf-8"><title>Offline</title>' +
        '<body style="font-family:system-ui;padding:2rem">You are offline and this page is not saved on this device.</body>',
      { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } },
    )
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return

  const url = new URL(request.url)

  // Same-origin only. Supabase API calls are the app's business — see the header
  // comment for why this worker has nothing to say about them.
  if (url.origin !== self.location.origin) return

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstDocument(request))
    return
  }

  if (isImmutableAsset(url)) {
    event.respondWith(cacheFirst(request))
  }
})
